    return (
        <div style={{display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap'}}>
            <Text variant="body-2" color="secondary">
                {t('languageLabel')}:
            </Text>
            <SegmentedRadioGroup
                size="m"
                value={language}
                onUpdate={(value) => setLanguage(value as Language)}
                options={[
