                    {value: 'ru', content: `🇷🇺 ${t('russian')}`},
                ]}
            />
        </div>
    );
}

function DemoPage() {
    const {t} = useLanguage();
    const [name, setName] = useState('');
    const [comment, setComment] = useState('');
