    const handleSave = () => setNotice(t('savedMessage'));
    const handleReset = () => {
        setName('');
        setComment('');
        setNotice(t('resetMessage'));
    };

    return (
        <div
            style={{
                minHeight: '100vh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: 24,
            }}
        >
            <Card style={{width: '100%', maxWidth: 520, padding: 32}}>
                <div style={{display: 'flex', flexDirection: 'column', gap: 20}}>
                    <div>
                        <Text variant="header-1" as="h1">
                            {t('appTitle')}
                        </Text>
                        <Text variant="body-2" color="secondary" as="p">
                            {t('subtitle')}
                        </Text>
                    </div>

                    <LanguageSwitcher />

                    <div>
                        <Text variant="subheader-2" as="h2">
                            {t('greeting')}
                        </Text>
                        <Text variant="body-2" as="p">
                            {t('intro')}
                        </Text>
                    </div>

                    <div style={{display: 'flex', flexDirection: 'column', gap: 12}}>
                        <TextInput
                            label={t('nameLabel')}
                            placeholder={t('namePlaceholder')}
                            value={name}
                            onUpdate={setName}
                        />
                        <TextArea
                            placeholder={t('commentPlaceholder')}
                            value={comment}
                            onUpdate={setComment}
                            minRows={3}
                        />
                        <Text variant="caption-2" color="secondary">
                            {t('charactersTyped')}: {name.length + comment.length}
                        </Text>
                    </div>

                    <div style={{display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap'}}>
