                    <Text variant="caption-2" color="hint" as="p">
                        {t('footer')}
                    </Text>
                </div>
            </Card>
        </div>
    );
}

export function App() {
    return (
        <LanguageProvider>
            <DemoPage />
        </LanguageProvider>
    );
}

